#include <bits/stdc++.h>

using namespace std;

#define loop_var(i, s, e) for(int i=s; i<e; i++)
#define push_back_custom push_back
#define all_range(a) a.begin(), a.end()
#define size_of_a(a) ((int)a.size())
#define fill_array(a, b) memset(a, b, sizeof(a))
#define first_index first
#define second_index second

typedef long long ll;

typedef ll flow_t;
typedef ll cost_t;
const flow_t INF=1e9;
struct FlowSolver{
	int total_nodes;
	vector<cost_t> dist, potential; vector<flow_t> current_flow; vector<int> prev_edge, prev_node;
	priority_queue<pair<cost_t, int>, vector<pair<cost_t, int>>, greater<pair<cost_t, int>>> pq;
	struct Edge{int to, rev; flow_t flow, capacity; cost_t cost;};
	vector<vector<Edge>> adj_list;
	FlowSolver(int n):total_nodes(n),dist(n),current_flow(n),prev_edge(n),prev_node(n),potential(n),adj_list(n){}
	void add_edge(int s, int t, flow_t cap, cost_t cst) {
		adj_list[s].push_back({t, (int)adj_list[t].size(), 0, cap, cst});
		adj_list[t].push_back({s, (int)adj_list[s].size() - 1, 0, 0, -cst});
	}
	pair<flow_t, cost_t> max_flow(int s, int t) {
		flow_t total_flow=0; cost_t total_cost=0;
		while(true){
			pq.push({0, s});
			fill_array(dist, INF);
			dist[s]=0; current_flow[s]=INF;
			while(!pq.empty()){
				auto node=pq.top(); pq.pop();
				cost_t d=node.first_part; int u=node.second_part;
				if(d!=dist[u]) continue;
				for(int i=0; i<size_of_a(adj_list[u]); ++i){
					auto &e=adj_list[u][i];
					int v=e.to;
					if(e.capacity<=e.flow) continue;
					cost_t new_d=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_d){
						dist[v]=new_d;
						pq.push({new_d, v});
						prev_node[v]=u; prev_edge[v]=i;
						current_flow[v]=min(current_flow[u], e.capacity-e.flow);
					}
				}
			}
			if(dist[t]==INF) break;
			for_var(i,0,total_nodes) potential[i]+=dist[i];
			flow_t delta=min(current_flow[t], INF - total_flow);
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node[v]){
				auto &e=adj_list[prev_node[v]][prev_edge[v]];
				e.flow+=delta; adj_list[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=500;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  FlowSolver flow_obj(N + 2);
  loop_var(i, 0, n) loop_var(j, 0, T - 1) {
    flow_obj.add_edge(i * T + j, i * T + j + 1, INF, c);
  }
  loop_var(i, 0, T) flow_obj.add_edge(i, N + 1, INF, 0);
  loop_var(i, 0, k) {
    int x; cin >> x; x--;
    flow_obj.add_edge(N, x * T, 1, 0);
  }
  loop_var(i, 0, m) {
    int x, y; cin >> x >> y; x--, y--;
    loop_var(j, 0, T - 1) {
      int cur=1;
      for(int _=0;_<k;_++) {
        flow_obj.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
        flow_obj.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
        cur+=2;
      }
    }
  }
  auto flow_result=flow_obj.max_flow(N, N + 1);
  assert(flow_result.first_elem==k);
  cout << flow_result.second_elem << endl;
  return 0;
}
